535						row.record.queries.definitionOf.rawNs.pop();
536						row.stdout = serializePerformanceRecord(row.record);
537					});
538					resealEvidenceCopy(copy);
539				},
540			},
541			{
542				name: 'wrong process cap',
543				expected: /performance scale 10000 semantic mismatch/,
544				mutate(copy: string) {
545					mutateJsonLines(join(copy, 'raw/performance.jsonl'), ([row]) => {
