			format: ['esm'],
			outDir: './dist',
			platform: 'node',
			fixedExtension: false,
			dts: false,
			clean: true,
			deps: {
				neverBundle: [/^node:/, /^@guessless\/engine(?:\/.*)?$/],
				onlyBundle: false,
			},
		},
		{
			name: '@guessless/oracle',
			cwd: join(rootDir, 'packages/oracle'),
			entry: { cli: './src/cli.ts' },
			format: ['esm'],
			outDir: './dist',
			platform: 'node',
			fixedExtension: false,
			dts: false,
			clean: true,
			deps: {
				neverBundle: [
					/^node:/,
					/^@guessless\/engine(?:\/.*)?$/,
					/^pathe(?:\/.*)?$/,
					/^ufo(?:\/.*)?$/,
				],
				onlyBundle: false,
			},
		},
		{
			name: '@guessless/evaluation',
